class Solution {
public:
    long long maxDifference(vector<int>& nums) {
        int n = nums.size();
        long long dp1 = 0; // dp[i+1]
        long long dp2 = 0; // dp[i+2]
        for (int i = n - 1; i >= 0; i--) {
            long long s1 = nums[i];
            long long best = (s1 % 3 == 0) ? (s1 - dp1) : (s1 + dp1);
            if (i + 1 < n) {
                long long s2 = (long long)nums[i] + nums[i + 1];
                long long cand = (s2 % 3 == 0) ? (s2 - dp2) : (s2 + dp2);
                if (cand > best) best = cand;
            }
            dp2 = dp1;
            dp1 = best;
        }
        return dp1;
    }
};
